# -*- coding: utf-8 -*-
from common import md, esc, cq, verse_card
def rings():
    R=[(250,"#ff6b8b","直到地极","徒13–28 · 外邦世界 · 罗马"),(185,"#4fb3ff","撒马利亚","徒8 · 半个以色列"),(125,"#3fd39a","犹太全地","徒8–12 · 吕大、约帕、凯撒利亚"),(65,"#f5b942","耶路撒冷","徒1–7")]
    s='<figure class="glass reveal rings"><svg viewBox="0 0 560 560" role="img" aria-label="使徒行传1:8同心圆：耶路撒冷、犹太、撒马利亚、地极">'
    for i,(r,c,t,d) in enumerate(R):
        s+=f'<circle cx="280" cy="280" r="{r}" fill="{c}" fill-opacity=".14" stroke="{c}" stroke-width="3" class="ring" style="--d:{(3-i)*300}ms"/>'
        y=280-r+27 if r>65 else 275
        s+=f'<text x="280" y="{y}" text-anchor="middle" font-size="24" font-weight="800" fill="{c}">{t}</text><text x="280" y="{y+21 if r>65 else 302}" text-anchor="middle" font-size="15" fill="currentColor" opacity=".85">{d}</text>'
    s+='</svg><figcaption>“但圣灵降临在你们身上，你们就必得着能力，并要在耶路撒冷、犹太全地，和撒马利亚，直到地极，作我的见证。”（徒1:8）——全书的大纲：同心圆向外扩展。</figcaption></figure>'
    return s
PR=[("6:7","耶路撒冷","神的道兴旺起来；在耶路撒冷门徒数目加增的甚多","1–6:7"),("9:31","犹太 · 加利利 · 撒马利亚","各处的教会都得平安，被建立……人数就增多了","6:8–9:31"),("12:24","安提阿 · 外邦","神的道日见兴旺，越发广传","9:32–12:24"),
    ("16:5","小亚细亚","众教会信心越发坚固，人数天天加增","12:25–16:5"),("19:20","欧洲 · 以弗所","主的道大大兴旺，而且得胜","16:6–19:20"),("28:31","罗马","放胆传讲神国的道……并没有人禁止","19:21–28:31")]
def prchart():
    W=1000;H=330
    s=f'<svg viewBox="0 0 {W} {H}" class="prc" role="img" aria-label="六个进展报告图">'
    pts=[]
    for i,(r,pl,t,rg) in enumerate(PR):
        x=90+i*165; y=240-i*38; pts.append((x,y))
        s+=f'<rect x="{x-60}" y="{y}" width="120" height="{290-y}" rx="10" fill="hsl({40+i*55},80%,60%)" fill-opacity=".28" stroke="hsl({40+i*55},80%,60%)"/><text x="{x}" y="{y-12}" text-anchor="middle" font-size="22" font-weight="800" fill="currentColor">徒{r}</text><text x="{x}" y="{min(y+30,280)}" text-anchor="middle" font-size="15" fill="currentColor">{pl.split(" · ")[0]}</text><text x="{x}" y="315" text-anchor="middle" font-size="14" fill="currentColor" opacity=".8">{rg}</text>'
    s+='<polyline points="'+" ".join(f"{x},{y-46}" for x,y in pts)+'" fill="none" stroke="#f5b942" stroke-width="4" stroke-dasharray="8 6" class="draw"/>'
    return s+'</svg>'
SP=[("彼得","五旬节","2:14-40","犹太群众","约珥 2；诗 16；诗 110","你们钉死的，神立祂为主为基督；悔改受洗"),("彼得","所罗门廊","3:12-26","圣殿百姓","申 18；创 22","生命的主被杀；先知像摩西；万族得福"),("彼得","公会","4:8-12","宗教领袖","诗 118","除祂以外别无拯救"),
    ("司提反","公会","7:2-53","公会","以色列历史全览","神不住人手所造的；你们常时抗拒圣灵"),("彼得","哥尼流家","10:34-43","外邦人","（宣讲耶稣生平）","神不偏待人；凡信祂的人必因祂的名得蒙赦罪"),
    ("保罗","彼西底安提阿","13:16-41","会堂","诗 2；赛 55；诗 16；哈 1","大卫的后裔；因信称义，非摩西律法所能"),("保罗","路司得","14:15-17","异教群众","（自然启示）","离弃虚妄，归向创造天地的永生神"),("雅各","耶路撒冷会议","15:13-21","使徒和长老","摩 9","外邦人不必先成为犹太人"),
    ("保罗","亚略巴古","17:22-31","希腊哲学家","（引希腊诗人）","未识之神；悔改；复活与审判"),("保罗","米利都","20:18-35","以弗所长老","—","牧养神用血买来的教会"),("保罗","耶路撒冷台阶","22:1-21","犹太群众","—","归信见证 ②"),("保罗","亚基帕王前","26:2-23","王与巡抚","摩西与先知","归信见证 ③；从黑暗归向光明")]
LA=[("献给提阿非罗","路1:3","徒1:1"),("圣灵降在耶稣身上 → 开始工作","路3:22","徒2:1-4"),("就职讲道引先知书","路4:16-21（以赛亚）","徒2:14-21（约珥）"),("医治瘫子","路5:17-26","徒3:1-10；徒9:32-35"),("百夫长的信心","路7:1-10","徒10"),("使寡妇的儿子/女人复活","路7:11-17","徒9:36-43"),
    ("定意上耶路撒冷","路9:51","徒19:21"),("在大祭司、巡抚、希律王前受审","路22–23","徒23–26"),("三次被宣告无罪","路23:4,14,22","徒23:29；徒25:25；徒26:31"),("“父啊，饶恕他们”/“主啊，不要将这罪归于他们”","路23:34","徒7:60"),("“父啊，我将我的灵魂交在你手里”/“求主耶稣接收我的灵魂”","路23:46","徒7:59")]
PP=[("医治生来瘸腿的","3:1-10","14:8-10"),("对付行邪术的","8:18-24（西门）","13:6-12（以吕马）"),("人要向他们下拜","10:25-26","14:13-15"),("使死人复活","9:36-41（大比大）","20:9-12（犹推古）"),("神迹从身上发出","5:15（影儿）","19:12（手巾围裙）"),("奇妙出监","12:6-11","16:25-34"),("被大祭司公会审问","4–5","22:30–23:10")]
def build():
    b=[]
    b.append('<h2 id="n1">一、作者 · 读者 · 年代</h2>')
    F=[("✍️","作者：路加","医生（{{西4:14}}），保罗的同工；“我们”段落（{{徒16:10-17}}；{{徒20:5–21:18}}；{{徒27:1–28:16}}）显示他亲历其事。早期教会（穆拉多利残篇、爱任纽）一致认定路加。"),
       ("📨","读者：提阿非罗","“大人”（{{路1:3}}）可能是一位有地位的罗马人，已受教导，需要“确实”（{{路1:4}}）。也代表所有“爱神的人”（名字的含义）。"),
       ("📅","年代：约主后 62 年","书在保罗软禁两年后戛然而止（{{徒28:30}}）；没有提到 64 年尼禄大火与逼迫、62 年雅各殉道、70 年圣殿被毁。保守学者多定于 62 年前后（也有 70–80 年代之说）。"),
       ("📏","篇幅","28 章、1007 节；与路加福音合占新约约四分之一——路加是新约篇幅最多的作者。")]
    b.append('<div class="why3">'+"".join(f'<div class="w3 glass reveal"><span>{a}</span><b>{c}</b><p>{md(d)}</p></div>' for a,c,d in F)+'</div>')
    b.append('<h2 id="n2">二、为什么写？——五个目的</h2>')
    P=[("🔗","接续“开头”","耶稣“开头”所行所教（{{徒1:1}}），在升天后藉圣灵与使徒**继续**：教会的历史就是基督的工作。"),
       ("🌍","证明万国蒙福","神的救恩从犹太人到撒马利亚人、太监、外邦人：亚伯拉罕之约与先知应许的应验（{{徒13:47}}）。"),
       ("⚖️","辩护（apologia）","罗马官员一再宣告基督徒无罪（迦流、吕西亚、非斯都、亚基帕）：福音不是颠覆罗马的运动。"),
       ("📜","证实保罗","保罗与彼得、耶路撒冷教会在福音上一致；外邦人宣教出于神，不是保罗的私意。"),
       ("💪","坚固教会","面对逼迫与内部问题，读者确知：神的道不被捆绑，**主的道大大兴旺，而且得胜**（{{徒19:20}}）。")]
    b.append('<div class="why3">'+"".join(f'<div class="w3 glass reveal"><span>{a}</span><b>{c}</b><p>{md(d)}</p></div>' for a,c,d in P)+'</div>')
    b.append('<h2 id="n3">三、全书大纲：1:8 同心圆</h2>'+rings()+verse_card("徒1:8"))
    b.append('<h3 id="n3b">🧩 四段结构（本站分页）</h3><div class="tbl"><table><thead><tr><th>段落</th><th>章</th><th>中心城市</th><th>主角</th><th>主题</th><th>年代</th></tr></thead><tbody>'+
      "".join(f'<tr><td><a href="{h}"><b>{a}</b></a></td><td>{c}</td><td>{d}</td><td>{e}</td><td>{f}</td><td>{g}</td></tr>' for a,c,d,e,f,g,h in [
      ("🔥 耶路撒冷","1–7","耶路撒冷","彼得、司提反","圣灵降临、教会诞生、逼迫","30–34","jerusalem.html"),("🌊 犹太·撒马利亚","8–12","撒马利亚、约帕、凯撒利亚、安提阿","腓利、扫罗、彼得","福音跨越种族边界","34–44","samaria.html"),
      ("⛵ 宣教旅行","13–19","安提阿 → 小亚细亚 → 欧洲 → 以弗所","保罗、巴拿巴、西拉","外邦人教会建立","46–57","missions.html"),("⛓️ 往罗马","20–28","耶路撒冷 → 凯撒利亚 → 罗马","被囚的保罗","见证到帝国心脏","57–62","rome.html")])+'</tbody></table></div>')
    b.append('<h2 id="n4">四、六个进展报告：道的增长</h2><figure class="glass reveal gwrap">'+prchart()+'<figcaption>'+md("路加用六个“总结句”把全书分成六段：每一段都以**神的道兴旺**收尾，地理范围不断扩大。")+'</figcaption></figure>')
    b.append('<div class="tbl"><table><thead><tr><th>报告</th><th>范围</th><th>经文（和合本）</th><th>段落</th></tr></thead><tbody>'+"".join(f'<tr><td><b class="key">徒{r}</b></td><td>{pl}</td><td>{md("{{徒"+r+"}}")}</td><td>{rg}</td></tr>' for r,pl,t,rg in PR)+'</tbody></table></div>')
    b.append('<h2 id="n5">五、讲道一览（全书约三分之一是讲章）</h2><div class="tbl"><table><thead><tr><th>讲者</th><th>场合</th><th>经文</th><th>听众</th><th>引用旧约</th><th>核心</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>徒{d}</td><td>{e}</td><td>{f}</td><td>{g}</td></tr>' for a,c,d,e,f,g in SP)+'</tbody></table></div>')
    b.append(f'<div class="callout key-c"><b>⭐ 讲道的共同骨架（kerygma）：</b>{md("①旧约应许已应验 → ②耶稣的生平、受死（人的罪）→ ③神叫祂复活（神的翻案）→ ④使徒是见证人 → ⑤**悔改、信、受洗、得赦罪与圣灵** → ⑥将来的审判。这正是改革宗讲道「以基督为中心、以圣经为根据、呼召悔改信靠」的范本。")}</div>')
    b.append('<h2 id="n6">六、文学设计：平行结构</h2><h3 id="n6a">🪞 路加福音 ↔ 使徒行传</h3><div class="tbl"><table><thead><tr><th>主题</th><th>路加福音</th><th>使徒行传</th></tr></thead><tbody>'+"".join(f'<tr><td>{a}</td><td>{c}</td><td>{d}</td></tr>' for a,c,d in LA)+'</tbody></table></div><p class="note">平行的目的：<b class="key">教会走主所走的路</b>——同一圣灵、同一使命、同样受苦、同样得胜。</p>')
    b.append('<h3 id="n6b">⚖️ 彼得 ↔ 保罗</h3><div class="tbl"><table><thead><tr><th>事件</th><th>彼得（1–12）</th><th>保罗（13–28）</th></tr></thead><tbody>'+"".join(f'<tr><td>{a}</td><td>徒{c}</td><td>徒{d}</td></tr>' for a,c,d in PP)+'</tbody></table></div><p class="note">平行的目的：证明外邦人的使徒保罗与犹太人的使徒彼得有同样的权柄、传同一福音（参 {{加2:7-9}}）。</p>'.replace("{{加2:7-9}}","加2:7-9"))
    b.append('<h2 id="n7">七、怎样读：描述性 vs 规范性</h2><div class="two"><div class="card glass"><h4>✅ 规范性（今天仍要遵行）</h4><ul class="apps"><li>'+md("经文明确吩咐、书信确认：悔改、信、受洗（{{徒2:38}}）；恒守使徒教训、交接、擘饼、祈祷（{{徒2:42}}）")+'</li><li>'+md("按立长老（{{徒14:23}}；{{徒20:28}}）")+'</li><li>'+md("顺从神不顺从人（{{徒5:29}}）")+'</li><li>'+md("向万民传福音（{{徒1:8}}）")+'</li></ul></div><div class="card glass"><h4>📜 描述性（一次性/不作模板）</h4><ul class="apps"><li>'+md("五旬节的风声与火舌；**圣灵降临的四个里程碑**（2、8、10、19 章）")+'</li><li>'+md("凡物公用（自愿而非强制，{{徒5:4}}）")+'</li><li>'+md("掣签选使徒（圣灵降临前，{{徒1:26}}）")+'</li><li>'+md("使徒的神迹奇事（“使徒的凭据”，{{林后12:12}}）")+'</li></ul></div></div>')
    b.append(cq(("bc",7,"我们相信，圣经中包含了神全部的旨意；我们也相信它对人得救所必须信的一切真理作了充分的教导。")))
    return "".join(b)
